/// Test merge_manifest preserves track fields correctly
#[test]
fn test_merge_manifest_preserves_track_fields() {
    use session_api::store_persistence_types::PersistedSessionManifest;
    use session_api::SessionMetadata;
    use session_api::SessionLinks;
    use chrono::Utc;

    let now = Utc::now();

    // Existing manifest with track_id set
    let existing = PersistedSessionManifest {
        schema_version: 1,
        session_id: "test-session".to_string(),
        source: "test".to_string(),
        started_at: now,
        captured_at: now,
        metadata: SessionMetadata::default(),
        links: SessionLinks::default(),
        track_id: Some("track-123".to_string()),
        anchor_ticket_id: Some("ticket-456".to_string()),
        parent_session_id: Some("parent-789".to_string()),
        spawned_session_id: None,
    };

    // Incoming manifest without track fields
    let incoming = PersistedSessionManifest {
        schema_version: 1,
        session_id: "test-session".to_string(),
        source: "test".to_string(),
        started_at: now,
        captured_at: now,
        metadata: SessionMetadata::default(),
        links: SessionLinks::default(),
        track_id: None,
        anchor_ticket_id: None,
        parent_session_id: None,
        spawned_session_id: None,
    };

    // Use the internal merge function via the store module
    // Since merge_manifest is pub(super), we test via store operations
    use session_api::store::helpers::storage::merge_manifest;

    let merged = merge_manifest(Some(existing.clone()), incoming);

    // Track fields should be preserved from existing when incoming is None
    assert_eq!(merged.track_id, Some("track-123".to_string()));
    assert_eq!(merged.anchor_ticket_id, Some("ticket-456".to_string()));
    assert_eq!(merged.parent_session_id, Some("parent-789".to_string()));
    assert_eq!(merged.spawned_session_id, None);

    println!("✓ merge_manifest preserves existing track fields when incoming is None");

    // Test incoming non-None values override existing
    let incoming_with_new_track = PersistedSessionManifest {
        track_id: Some("new-track-999".to_string()),
        ..incoming.clone()
    };

    let merged2 = merge_manifest(Some(existing.clone()), incoming_with_new_track);

    // Incoming non-None should override existing
    assert_eq!(merged2.track_id, Some("new-track-999".to_string()));
    // Other fields still preserved
    assert_eq!(merged2.anchor_ticket_id, Some("ticket-456".to_string()));

    println!("✓ merge_manifest prefers incoming non-None track fields");
}

/// Test round-trip: write session with track fields, read back, merge, verify
#[test]
fn test_track_fields_roundtrip() -> Result<(), SessionError> {
    use session_api::{SessionRecord, SessionMetadata, SessionLinks};
    use chrono::Utc;
    use tempfile::TempDir;

    let temp_dir = TempDir::new()?;
    let config = SessionStoreConfig {
        store_root: temp_dir.path().to_path_buf(),
        workspace_slug: "test".to_string(),
    };

    let store = SessionStore::new(config)?;

    let now = Utc::now();
    let session_id = "roundtrip-session-123".to_string();

    // Create a session with track fields
    let mut session = SessionRecord {
        schema_version: 1,
        session_id: session_id.clone(),
        source: "test".to_string(),
        started_at: now,
        captured_at: now,
        metadata: SessionMetadata::default(),
        turns: vec![],
        links: SessionLinks::default(),
        track_id: Some("track-xyz".to_string()),
        anchor_ticket_id: Some("ticket-abc".to_string()),
        parent_session_id: Some("parent-def".to_string()),
        spawned_session_id: Some("spawned-ghi".to_string()),
    };

    // Write to store
    store.capture(session.clone())?;

    // Read back
    let loaded = store.get(&session_id)?;

    // Verify all track fields preserved
